) values
  ('TOUR-01', 'mot-ngay-lam-nong-dan-cu-lao-chu-ba-minh', 'farm-ba-minh-tan-trieu', 'Vườn Bưởi Chú Ba Minh', '26188', 'Phường Tân Triều', 'Tân Triều & Trung tâm', 'bilingual_tour', 'Một ngày làm nông dân cù lao Tân Triều & Workshop đóng gói QR (Song ngữ VI/EN)', 'Tan Trieu Alluvial Pomelo Harvest & QR Traceability Workshop (Bilingual VI/EN)', 'Khám phá cù lao Tân Triều, trải nghiệm cắt bưởi đường lá cam đúng độ chín, đo độ Brix và tự tay dán tem QR nguồn gốc cùng Chú Ba Minh.', 'Explore historic Tan Trieu pomelo gardens along the Dong Nai River, check Brix sweetness, and practice packing traceable QR fruit boxes.', 'Thu hoạch đều từ tháng 9 đến tháng 12 âm lịch (liên hệ trước theo ca mở).', 'Harvest availability varies by batch schedule; check open slot capacity before visiting.', 3, 120000, 65000, 2, 16, '{vi,en}', 'all_ages', 'Lối đi bê tông nhẹ bằng phẳng, phù hợp gia đình có người lớn tuổi và xe đẩy trẻ em.', 'Mostly flat shaded garden paths suitable for multi-generation families.', 'Có nếm bưởi tươi và mứt vỏ bưởi mật ong (không phục vụ rượu bưởi cho người dưới 18 tuổi).', 'Includes fresh pomelo & honeyed pomelo peel tasting; no nuts unless requested.', 'Đi cùng hướng dẫn viên theo hàng bưởi, mang giày bít mũi hoặc sandal bám tốt.', 'Stay on marked orchard paths with the assigned youth guide; closed-toe shoes recommended.', 'Nếu mưa lớn kéo dài, hoạt động chuyển sang khu nhà mát thực hành đóng gói & QR.', 'During heavy rain, orchard harvesting moves under the sheltered packing pavilion.', 'Cổng Vườn Chú Ba Minh · Cù lao Tân Triều, Phường Tân Triều (vị trí gần đúng theo khu vực)', 'Uncle Ba Minh Orchard Gate · Tan Trieu Ward (approximate cluster location)', false, '["Hướng dẫn viên song ngữ VI/EN (Thanh niên Tình nguyện)","Thưởng thức 2 múi bưởi & trà lá bưởi tại vườn","Thực hành in và quét thử mã lô NF-TT-2026-01"]', '["Bilingual youth ambassador guide (VI/EN)","Seasonal pomelo tasting & herbal pomelo leaf tea","Hands-on QR batch passport & sorting session"]', '[{"timeLabel":"08:30","titleVi":"Đón khách & phổ biến an toàn vườn","titleEn":"Welcome briefing & orchard safety check","detailVi":"Giới thiệu lịch sử đất phù sa Tân Triều và hướng dẫn đi đúng lối liếp vườn.","detailEn":"Introduce alluvial soil history, sun protection, and marked walkway rules."},{"timeLabel":"09:15","titleVi":"Thăm liếp bưởi & kiểm tra độ ngọt Brix","titleEn":"Alluvial grove walk & Brix sweetness demonstration","detailVi":"Quan sát cách bọc trái sinh học và thu hái bưởi bằng kéo chuyên dụng.","detailEn":"Learn bio-bagging and clean stem clipping techniques."},{"timeLabel":"10:15","titleVi":"Workshop gắn tem QR & thưởng thức đặc sản","titleEn":"QR passport tagging & orchard tasting","detailVi":"Tự tay quét mã QR xem lại nhật ký chăm sóc của chính trái vừa hái.","detailEn":"Scan real batch codes and sample fresh pomelo with honeyed peel snacks."}]', '[{"id":"SLOT-TT-01","dateIso":"2026-11-28","startTime":"08:30","endTime":"11:30","capacity":16,"bookedCount":6,"guideId":"guide-minh-anh","guideName":"Minh Anh (TNV Song ngữ)","language":"bilingual","status":"open"},{"id":"SLOT-TT-02","dateIso":"2026-11-29","startTime":"08:30","endTime":"11:30","capacity":16,"bookedCount":13,"guideId":"guide-van-an","guideName":"Nguyễn Văn An (ĐH Đồng Nai)","language":"bilingual","status":"almost_full"},{"id":"SLOT-TT-03","dateIso":"2026-12-05","startTime":"08:30","endTime":"11:30","capacity":20,"bookedCount":8,"guideId":"guide-minh-anh","guideName":"Minh Anh & Tổ TNV","language":"bilingual","status":"open"}]', '["P06","P07","P11"]', '["NF-LIVE-REPLAY-TT"]', '/images/stitch/stitch-21.jpg', '["/images/stitch/stitch-19.jpg","/images/stitch/stitch-20.jpg","/images/stitch/stitch-24.jpg"]', 4.9, 18),
  ('TOUR-02', 'tham-quan-vuon-ba-tu-long-khanh', 'farm-ba-tu-demo', 'Nhà vườn Ba Tư', '26080', 'Phường Long Khánh', 'Long Khánh & Lân cận', 'harvest', 'Kể chuyện Chôm chôm & Sầu riêng 2,5 ha cùng Chú Ba Tư Long Khánh', 'Ba Tu Basalt Orchard Story: Rambutan Harvest & Durian Grove Walk', 'Gặp gỡ chú Ba Tư tại Phường Long Khánh, tìm hiểu cách 2 đoàn viên hỗ trợ chú bước lên chợ số và thử hái chôm chôm sáng sớm.', 'Meet 50-year-old grower Uncle Ba Tu on his 2.5 ha basalt orchard in Long Khanh Ward and trace batch NF-DEMO-001 from tree to basket.', 'Thu hoạch theo đợt chôm chôm Java & Ri6 (kiểm tra trạng thái mùa trong tuần).', 'Available on scheduled orchard mornings depending on weekly harvest maturity.', 2.5, 90000, 45000, 2, 14, '{vi,en}', 'family_6_plus', 'Đường đất đỏ bazan tương đối bằng, lưu ý tránh khu vực tán sầu riêng đang rụng trái.', 'Compacted red basalt trails; helmet provided under mature durian canopies.', 'Thử trái cây tươi theo mùa (chôm chôm, sầu riêng); ghi chú nếu dị ứng nhựa trái.', 'Fresh tropical fruit tasting (rambutan & durian); please flag latex or fruit sensitivities.', 'Không đứng trực tiếp dưới tán sầu riêng khi gió lớn; luôn đi cùng chủ vườn hoặc TNV.', 'Never stand directly beneath fruiting durian trees; follow youth escorts at all times.', 'Dời sang lán phân loại rơm nếu trời mưa giông.', 'Moves into the covered sorting shed during afternoon squalls.', 'Điểm hẹn Ấp Bàu Cối, Phường Long Khánh (chỉ dẫn cụ thể sau xác nhận chủ vườn)', 'Bau Coi Hub, Long Khanh Ward (exact meeting pin shared upon host confirmation)', false, '["Nước chôm chôm mát & nếm trái cây tại vườn","Xem quy trình 3 bước Chụp ảnh & Giọng nói của Chú Ba Tư","Hỗ trợ đóng gói giỏ quà 2 kg (mua thêm tùy nhu cầu)"]', '["Welcome orchard drink & fresh seasonal fruit plate","Live demonstration of 3-step photo & voice farm listing","Optional direct orchard pickup order packing"]', '[{"timeLabel":"08:30","titleVi":"Gặp chú Ba Tư & thăm khu chôm chôm Java","titleEn":"Meet Uncle Ba Tu & Java Rambutan block walk","detailVi":"Tìm hiểu đất đỏ bazan và cách cắt chùm giữ cuống râu tươi.","detailEn":"Learn how volcanic basalt soil supports crisp Java rambutan."},{"timeLabel":"09:30","titleVi":"Thực hành quét lô NF-DEMO-001 & thăm vườn sầu riêng","titleEn":"Batch NF-DEMO-001 QR scan & Ri6 durian safety stop","detailVi":"Xem nhật ký bón phân hữu cơ và cách phân biệt độ chín cây.","detailEn":"Inspect grower-logged organic feeding records and durian pollination tags."}]', '[{"id":"SLOT-LK-01","dateIso":"2026-11-28","startTime":"08:30","endTime":"11:00","capacity":14,"bookedCount":5,"guideId":"guide-tuan","guideName":"Minh Anh & Tuấn","language":"bilingual","status":"open"},{"id":"SLOT-LK-02","dateIso":"2026-12-06","startTime":"08:30","endTime":"11:00","capacity":14,"bookedCount":2,"guideId":"guide-minh-anh","guideName":"Minh Anh","language":"bilingual","status":"open"}]', '["P01","P04","P05"]', '["NF-LIVE-01"]', '/images/stitch/stitch-40.jpg', '["/images/stitch/stitch-07.jpg","/images/stitch/stitch-04.jpg","/images/stitch/stitch-32.jpg"]', 4.8, 14),
  ('TOUR-03', 'trai-nghiem-xuong-rang-hat-dieu-xuan-loc', 'farm-htx-xuan-loc', 'HTX Nông nghiệp Xuân Lộc', '26425', 'Phường Xuân Lộc', 'Xuân Lộc & Đông Nam', 'processing', 'Từ hạt điều thô đến hũ điều rang củi Xuân Lộc (Kèm cảnh báo dị ứng hạt)', 'From Raw Nut to Wood-Fired Roasted Cashews at Xuan Loc Cooperative', 'Tìm hiểu vì sao quả điều có hai phần quả giả – hạt thật, xem kỹ thuật tách nhựa vỏ và rang củi truyền thống giữ vỏ lụa.', 'Learn cashew botany, safe shell processing, and traditional wood-fired cast-iron roasting paired with batch QR tracking.', 'Hoạt động xưởng quanh năm vào các buổi sáng thứ Sáu – Chủ Nhật.', 'Roastery demonstrations operate year-round Friday through Sunday mornings.', 2, 95000, 50000, 4, 18, '{vi,en}', 'school_supervised', 'Khu vực quan sát bếp rang có vạch an toàn cách chảo nhiệt 2 m.', 'Designated barrier 2m clear of wood-fired roasting pans; wheelchair-accessible hall.', 'CẢNH BÁO DỊ ỨNG: Có hạt điều (tree nuts) trong toàn khu xưởng và khu vực dùng thử.', 'ALLERGEN NOTICE: Tree nuts (cashews) processed throughout facility and tasting area.', 'Không tự ý chạm vỏ điều thô chưa xử lý nhiệt; trẻ nhỏ đi cùng người lớn hoặc giáo viên giám sát.', 'Do not handle raw unprocessed cashew shells; keep clear of roasting heat lines.', 'Hoàn toàn trong xưởng có mái che thông thoáng, không ảnh hưởng bởi mưa.', 'Fully sheltered workshop hall — operates rain or shine.', 'Xưởng sơ chế HTX Xuân Lộc, Khu phố Gia Ray, Phường Xuân Lộc', 'Xuan Loc Cooperative Roastery Hall, Gia Ray, Xuan Loc Ward', false, '["Tài liệu học tập 2D ''Hành trình hạt điều Đồng Nai''","Nếm thử hạt điều W240 rang củi & trà búp ổi","Ghi nhận giờ ngoại khóa cho đoàn trường có đồng thuận phụ huynh"]', '["Illustrated 2D ''Dong Nai Cashew Journey'' handout","W240 wood-roasted cashew & roasted guava leaf tea tasting","Supervised school excursion sign-off available"]', '[{"timeLabel":"09:00","titleVi":"Phân biệt quả giả & hạt thật — Cảnh báo dị ứng & an toàn","titleEn":"Cashew fruit botany, allergen briefing & safety orientation","detailVi":"Nhận biết cấu tạo 2 lớp và quy định khoảng cách an toàn khu rang.","detailEn":"Inspect botanical anatomy and clear nut-allergen disclosures."},{"timeLabel":"09:45","titleVi":"Quan sát rang chảo gang & đóng hũ mã lô NF-XL-2026-03","titleEn":"Cast-iron roasting view & QR jar sealing","detailVi":"Theo dõi kiểm tra độ ẩm và dán tem truy xuất nguồn gốc.","detailEn":"Review moisture control logs and airtight batch labeling."}]', '[{"id":"SLOT-XL-01","dateIso":"2026-11-30","startTime":"09:00","endTime":"11:00","capacity":18,"bookedCount":7,"guideId":"guide-lan-phuong","guideName":"Lan Phương (TNV Xuân Lộc)","language":"bilingual","status":"open"}]', '["P08","P12"]', '["NF-LIVE-02"]', '/images/stitch/stitch-50.jpg', '["/images/stitch/stitch-39.jpg","/images/stitch/stitch-34.jpg","/images/stitch/stitch-05.jpg"]', 4.9, 11),
  ('TOUR-04', 'trai-nghiem-vuon-co-tu-sinh-thai-cam-my-4', 'farm-co-tu-cam-my', 'Vườn Cô Tư Sinh Thái', '26347', 'Xã Xuân Đường', 'Cẩm Mỹ & Định Quán', 'harvest', 'Tìm hiểu nuôi ong hoa nhãn & Quy trình tỉa trái sầu riêng — Vườn Cô Tư Sinh Thái', 'Morning Harvest Experience at Vườn Cô Tư Sinh Thái', 'Chương trình trải nghiệm 3.1 ha tại Xã Xuân Đường: tham quan vườn Sầu riêng hạt lép, Mật ong hoa nhãn, nghe chia sẻ quy trình an toàn và thực hành quét tem truy xuất.', 'Guided 3.1 ha orchard walk in Xã Xuân Đường featuring Sầu riêng hạt lép, Mật ong hoa nhãn, seasonal story sharing, and QR provenance checks.', 'Mùa vụ và số trái tại vườn phụ thuộc lịch cắt thực tế trong tuần; luôn xác nhận ca trước khi đi.', 'On-tree fruit availability depends on weekly harvest maturity; confirm host slot beforehand.', 2.5, 70000, 38500, 2, 15, '{vi,en}', 'all_ages', 'Địa hình vườn nông thôn có dốc nhẹ; liên hệ trước nếu đoàn cần xe hỗ trợ.', 'Rural orchard paths include natural earthen trails; notify host in advance for mobility support.', 'Thử nông sản tươi địa phương — vui lòng báo trước nếu có tiền sử dị ứng phấn hoa hoặc trái cây.', 'Seasonal fruit & honey tasting available — inform guide of pollen, honey, or fruit allergies.', 'Tuân thủ lối đi đánh dấu, giữ trẻ em trong tầm quan sát và kiểm tra đồng thuận trường học khi đi theo lớp.', 'Follow marked orchard paths, supervise minors at all times, and carry signed school consent.', 'Chuyển sang hoạt động phân loại trong nhà mát hoặc dời ca miễn phí khi mưa gió lớn.', 'Indoor QR/storytelling fallback or penalty-free reschedule during heavy rain.', 'Ấp Suối Lức, Xã Xuân Đường (vị trí gần đúng theo khu vực)', 'Ấp Suối Lức, Xã Xuân Đường (approximate area marker)', false, '["Hướng dẫn tham quan & kiểm tra nhật ký mùa vụ","Thưởng thức nông sản theo mùa tại vườn","Không thu phí giữ chỗ thật — thanh toán mô phỏng tại quầy"]', '["Guided orchard walk & diary trace walkthrough","Seasonal tasting plate at farm pavilion","Experience booking only — no online charge"]', '[{"timeLabel":"08:30","titleVi":"Đón đoàn & hướng dẫn an toàn, lưu ý dị ứng","titleEn":"Arrival welcome, safety & allergen check","detailVi":"Kiểm tra danh sách đoàn, phát nón/nước mát và giới thiệu đặc điểm đất vùng.","detailEn":"Confirm group roster, hand out sun hats, and review site safety."},{"timeLabel":"09:30","titleVi":"Trải nghiệm vườn & kiểm tra tem QR lô hàng","titleEn":"Orchard activity & live QR lot verification","detailVi":"Tìm hiểu quy trình chăm sóc thực tế của hộ vườn.","detailEn":"Explore cultivation diary entries and harvest steps on site."}]', '[{"id":"SLOT-04-AM","dateIso":"2026-11-27","startTime":"08:30","endTime":"11:00","capacity":15,"bookedCount":3,"guideId":"guide-1","guideName":"Đội TNV Xã Xuân Đường","language":"bilingual","status":"open"},{"id":"SLOT-04-PM","dateIso":"2026-11-27","startTime":"14:30","endTime":"16:30","capacity":12,"bookedCount":2,"guideId":"guide-1","guideName":"Đội TNV Xã Xuân Đường","language":"vi","status":"open"}]', '["P09","P76"]', '["NF-LIVE-01"]', '/images/stitch/stitch-38.jpg', '["/images/stitch/stitch-49.jpg","/images/stitch/stitch-06.jpg"]', 4.7, 6),
  ('TOUR-05', 'trai-nghiem-htx-nong-nghiep-xuan-loc-5', 'farm-htx-xuan-loc', 'HTX Nông nghiệp Xuân Lộc', '26425', 'Phường Xuân Lộc', 'Xuân Lộc & Đông Nam', 'storytelling', 'Trải nghiệm xưởng rang hạt điều củi & Đóng gói nông sản — HTX Nông nghiệp Xuân Lộc', 'Orchard Story & Tea Session at HTX Nông nghiệp Xuân Lộc', 'Chương trình trải nghiệm 12 ha tại Phường Xuân Lộc: tham quan vườn Hạt điều rang muối vỏ lụa, Cà phê rang mộc, nghe chia sẻ quy trình an toàn và thực hành quét tem truy xuất.', 'Guided 12 ha orchard walk in Phường Xuân Lộc featuring Hạt điều rang muối vỏ lụa, Cà phê rang mộc, seasonal story sharing, and QR provenance checks.', 'Mùa vụ và số trái tại vườn phụ thuộc lịch cắt thực tế trong tuần; luôn xác nhận ca trước khi đi.', 'On-tree fruit availability depends on weekly harvest maturity; confirm host slot beforehand.', 2.5, 90000, 49500, 2, 15, '{vi}', 'all_ages', 'Địa hình vườn nông thôn có dốc nhẹ; liên hệ trước nếu đoàn cần xe hỗ trợ.', 'Rural orchard paths include natural earthen trails; notify host in advance for mobility support.', 'Cảnh báo dị ứng: có hạt điều / sản phẩm từ hạt trong khu sơ chế.', 'Allergen warning: contains tree nuts (cashew) during tasting and workshop.', 'Tuân thủ lối đi đánh dấu, giữ trẻ em trong tầm quan sát và kiểm tra đồng thuận trường học khi đi theo lớp.', 'Follow marked orchard paths, supervise minors at all times, and carry signed school consent.', 'Chuyển sang hoạt động phân loại trong nhà mát hoặc dời ca miễn phí khi mưa gió lớn.', 'Indoor QR/storytelling fallback or penalty-free reschedule during heavy rain.', 'Khu phố Gia Ray, Phường Xuân Lộc (vị trí gần đúng theo khu vực)', 'Khu phố Gia Ray, Phường Xuân Lộc (approximate area marker)', false, '["Hướng dẫn tham quan & kiểm tra nhật ký mùa vụ","Thưởng thức nông sản theo mùa tại vườn","Không thu phí giữ chỗ thật — thanh toán mô phỏng tại quầy"]', '["Guided orchard walk & diary trace walkthrough","Seasonal tasting plate at farm pavilion","Experience booking only — no on